from fractions import Fraction


def expected_turns(n: int, m: int, jumps: list[list[int]]) -> list[int] | None:
    jump_to = dict(jumps)

    destination = list(range(n + 1))
    for cell in range(n + 1):
        end = cell
        while end in jump_to:
            end = jump_to[end]
        destination[cell] = end

    states = [0]
    seen = {0}
    transitions = {}
    reverse = [[] for _ in range(n + 1)]

    for position in states:
        counts = {}
        for roll in range(1, m + 1):
            landing = position + roll
            if landing > n:
                landing = 2 * n - landing
            landing = destination[landing]
            counts[landing] = counts.get(landing, 0) + 1

        transitions[position] = counts
        for landing in counts:
            reverse[landing].append(position)
            if landing != n and landing not in seen:
                seen.add(landing)
                states.append(landing)

    # Every reachable state must have a path to the terminal cell.
    can_finish = {n}
    stack = [n]
    while stack:
        cell = stack.pop()
        for previous in reverse[cell]:
            if previous not in can_finish:
                can_finish.add(previous)
                stack.append(previous)

    if any(state not in can_finish for state in states):
        return None

    size = len(states)
    index = {state: i for i, state in enumerate(states)}
    matrix = [[0] * (size + 1) for _ in range(size)]

    # m * E[state] - sum(count * E[next_state]) = m.
    for i, state in enumerate(states):
        matrix[i][i] = m
        matrix[i][-1] = m
        for landing, count in transitions[state].items():
            if landing != n:
                matrix[i][index[landing]] -= count

    # Bareiss elimination keeps all intermediate matrix entries integral.
    previous_pivot = 1
    for column in range(size - 1):
        if matrix[column][column] == 0:
            pivot_row = next(
                row
                for row in range(column + 1, size)
                if matrix[row][column] != 0
            )
            matrix[column], matrix[pivot_row] = (
                matrix[pivot_row],
                matrix[column],
            )

        pivot = matrix[column][column]
        pivot_values = matrix[column]
        for row in range(column + 1, size):
            values = matrix[row]
            factor = values[column]
            for j in range(column + 1, size + 1):
                values[j] = (
                    pivot * values[j] - factor * pivot_values[j]
                ) // previous_pivot
            values[column] = 0
        previous_pivot = pivot

    expectations = [Fraction(0) for _ in range(size)]
    for i in range(size - 1, -1, -1):
        value = Fraction(matrix[i][-1])
        for j in range(i + 1, size):
            value -= matrix[i][j] * expectations[j]
        expectations[i] = value / matrix[i][i]

    answer = expectations[0]
    return [answer.numerator, answer.denominator]
